import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"文档站部署与维护","description":"","frontmatter":{},"headers":[],"relativePath":"deploy.md","filePath":"deploy.md","lastUpdated":1791601077000}'),n={name:"deploy.md"};function o(l,s,d,r,h,c){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="文档站部署与维护" tabindex="-1">文档站部署与维护 <a class="header-anchor" href="#文档站部署与维护" aria-label="Permalink to &quot;文档站部署与维护&quot;">​</a></h1><p>本站使用 <strong>VitePress 1.6.4 + Cloudflare Workers Static Assets</strong>，没有数据库或后端服务。独立 Worker 名称 <code>smart-contract-learn-docs</code>，已上线域名 <code>contract.majhoon.site</code>，备用 <code>docs.contract.majhoon.site</code>。</p><h2 id="本地预览" tabindex="-1">本地预览 <a class="header-anchor" href="#本地预览" aria-label="Permalink to &quot;本地预览&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>建议 Node.js 20+，避免在 2C2G 小服务器上同时构建多个项目。若内存不足，可限制 Node heap，例如 <code>NODE_OPTIONS=--max-old-space-size=256</code>。</p><h2 id="部署命令" tabindex="-1">部署命令 <a class="header-anchor" href="#部署命令" aria-label="Permalink to &quot;部署命令&quot;">​</a></h2><p>先在 Cloudflare 账户配置有效 API Token，其权限至少要足以编辑指定账户的 Worker，以及操作自定义域名所属 Zone。<strong>不要把 Token 提交到 Git 或写入 README</strong>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler.jsonc</span></span></code></pre></div><p>Wrangler 配置中的 custom domain 会尝试让 Cloudflare 为此子域创建 DNS 记录和证书；若域名已经绑定其他服务，必须先确认冲突再操作。</p><h2 id="低内存服务器专用-github-远程构建" tabindex="-1">低内存服务器专用：GitHub 远程构建 <a class="header-anchor" href="#低内存服务器专用-github-远程构建" aria-label="Permalink to &quot;低内存服务器专用：GitHub 远程构建&quot;">​</a></h2><p>为避免服务器上 <code>npm install</code> 或构建占满内存，仓库的 <code>.github/workflows/publish-assets.yml</code> 会在 GitHub Actions 中构建 VitePress，并将静态资源推送到 <code>cf-dist</code> 分支。</p><p>服务器部署时只需拉取 <code>cf-dist</code> 分支的<strong>已编译静态资源</strong>，然后用<strong>现成的 Wrangler 可执行程序</strong>执行 <code>wrangler deploy --assets &lt;已编译资源目录&gt; -c wrangler.jsonc</code>。这不需要在服务器安装 Node 依赖或本地构建。</p><p><strong>低内存发布门禁：</strong></p><ol><li>先提交教材变更到 <code>main</code>，由 GitHub Actions 远程安装依赖并构建；等待 <code>Build Docs Assets for Cloudflare</code> 成功，确认 <code>cf-dist</code> 已包含这次提交生成的产物。</li><li>服务器只下载 <code>cf-dist</code> 构建产物到<strong>独立临时目录</strong>，不要在正在使用的源码目录中清空文件或运行 <code>npm install</code>。</li><li>使用已安装、经过验证的 Wrangler CLI 上传静态产物。若当前仓库没有 <code>node_modules/.bin/wrangler</code>，<strong>不要用默认 <code>npx</code> 触发自动下载/安装</strong>，先查找此前用于发布的现有 CLI 路径或改用 GitHub 远程部署。</li><li>发布后检查域名主页、术语词典、Remix 新教程和排错页是否为 HTTP 200，再核对侧边栏能否进入这些页面；失败时不应假称已发布。</li></ol><p>本机<strong>不执行</strong> VitePress 构建、npm 依赖安装或 Foundry 测试，也不在低内存服务器上并发执行多个检查任务。</p><p>当前已采用该方法成功上线，<code>main</code> 分支仅保存源码，<code>cf-dist</code> 保存构建结果。Cloudflare Token 必须从可信的环境变量读取，不要写入部署脚本。</p><h2 id="可选-github-actions-全自动部署" tabindex="-1">可选：GitHub Actions 全自动部署 <a class="header-anchor" href="#可选-github-actions-全自动部署" aria-label="Permalink to &quot;可选：GitHub Actions 全自动部署&quot;">​</a></h2><p>仓库提供 <code>.github/workflows/deploy.yml</code>。在 GitHub 仓库 Settings → Secrets and variables → Actions 下配置两个 Secrets：<code>CLOUDFLARE_API_TOKEN</code> 和 <code>CLOUDFLARE_ACCOUNT_ID</code>，再新增 Repository Variable <code>ENABLE_CF_DEPLOY=true</code>。之后向 <code>main</code> 推送会触发远程构建和 Worker 部署，服务器无需自己编译。缺少这些值时该工作流会跳过部署，而不是假报成功。</p><p><code>.github/workflows/verify.yml</code> 已完成文档与 Foundry 合约的远程验证。<code>publish-assets.yml</code> 已成功生成 <code>cf-dist</code>。<strong>全自动 Cloudflare 工作流目前因缺少仓库授权配置而跳过；不要将其误认为已经自动发布。</strong></p><h2 id="发布后验收" tabindex="-1">发布后验收 <a class="header-anchor" href="#发布后验收" aria-label="Permalink to &quot;发布后验收&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://contract.majhoon.site/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://contract.majhoon.site/roadmap</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://contract.majhoon.site/05-project/escrow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://docs.contract.majhoon.site/</span></span></code></pre></div><p>检查是否为 2xx、TLS 是否正常、浏览器可打开侧边栏和搜索功能。并同步更新 <a href="/PROGRESS">内容进度</a>。</p><h2 id="版本约定" tabindex="-1">版本约定 <a class="header-anchor" href="#版本约定" aria-label="Permalink to &quot;版本约定&quot;">​</a></h2><ul><li>课程正文放 <code>docs/</code>，实操代码放 <code>examples/</code>。</li><li>每一篇新课程必须明确“目标、原理、源码、练习、失败用例、验收、常见坑”。</li><li><strong>测试、编译、发布状态分别标记</strong>；不要把“文档已写”说成“代码已上线”。</li><li>本地和 CI 日志严禁提交任何真实的私钥、助记词或 API Token。</li></ul>`,24)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
